// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

contract ApplicationPayment {

    address public owner; // deployer

    struct PaymentInfo {
        address payer; // address buyer
        string kantahCode; // kode kantah
        uint256 area; // luas tanah
        uint256 amount;
        uint256 timestamp;
    }

    mapping(string => PaymentInfo) public payments;

    // mapping harga tanah per meter disetiap kantah
    mapping(string => uint256) public kantahPrices;

    event PaymentReceived( 
        string indexed applicationId,
        string kantahCode,
        address indexed payer,
        uint256 area,
        uint256 amount,
        uint256 timestamp
    );

    constructor() {
        owner = msg.sender;
    }

    // function untuk mengatur harga tanah per meter disetiap kantah
    function setKantahPrice(
        string memory kantahCode,
        uint256 price
    ) external {
        require(msg.sender == owner, "Not owner");
        kantahPrices[kantahCode] = price;
    }

    // Function pembayaran
    function pay(
        string memory applicationId,
        string memory kantahCode,
        uint256 area
    )
        external
        payable
    {
        require(payments[applicationId].payer == address(0), "Already paid");

        uint256 price = kantahPrices[kantahCode];
        require(price > 0, "Price not set");

        uint256 requiredAmount = area * price;
        require(msg.value == requiredAmount, "Incorrect payment");

        payments[applicationId] = PaymentInfo({
            payer: msg.sender,
            kantahCode: kantahCode,
            area: area,
            amount: msg.value,
            timestamp: block.timestamp
        });

        emit PaymentReceived(
            applicationId,
            kantahCode,
            msg.sender,
            area,
            msg.value,
            block.timestamp
        );
    }

    // check apakah sudah dibayar
    function isPaid(string memory applicationId)
        external
        view
        returns (bool)
    {
        return payments[applicationId].payer != address(0);
    }

    // check pembayaran
    function getPaymentInfo(string memory applicationId)
        external
        view
        returns (PaymentInfo memory)
    {
        return payments[applicationId];
    }

    // tarik saldo
    function withdraw() external {
        require(msg.sender == owner, "Not owner");
        payable(owner).transfer(address(this).balance);
    }
}
